// Package literate reads a Quint model written in a Markdown document:
// its `quint` fenced blocks, in document order, are the model (ROADMAP
// CW1, L8). Tangle extracts them into a generated `.qnt` that carries the
// document's digest and a map from each of its lines to the document's,
// so a position quint or gotogether reports in the generated file
// (`doc.qnt:12:5`) is rewritten to the document's (`doc.md:48:5`) by
// Rewrite, with no state but the generated file itself.
//
// The generated file is written beside the document, named after it
// (`acquisition.md` → `acquisition.qnt`), so plain quint can run it and a
// generated replay module imports it by relative path as any other
// model. A file of that name that gotogether did not generate is never
// overwritten.
package literate

import (
	"bufio"
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
)

// Header is the generated file's first line's prefix: what marks a file
// as gotogether's, safe to replace.
const Header = "// Code generated by gotogether from "

const (
	digestPrefix = "// gotogether:literate sha256="
	linesPrefix  = "// gotogether:lines "
)

// A Tangled document: its model's source, and where each line came from.
type Tangled struct {
	// Doc is the document's path, as given to Tangle.
	Doc string
	// Source is the generated .qnt: the header, the blocks' lines, the map.
	Source []byte
	// Digest is the document's SHA-256, hex.
	Digest string
	// Lines maps a generated line (1-based, Lines[i] for line i+1) to the
	// document's, 0 for the generated header and map.
	Lines []int
	// Blocks counts the document's quint blocks.
	Blocks int
}

// fence matches a fenced block's opening: up to three spaces, then three
// or more backticks or tildes, then the info string.
var fence = regexp.MustCompile("^ {0,3}(`{3,}|~{3,})\\s*([^`\\s]*)")

// Tangle extracts doc's quint blocks (info string "quint", its first
// word) in order. A document with none, or a block left open, is an
// error naming the line and the fix.
func Tangle(path string, doc []byte) (*Tangled, error) {
	sum := sha256.Sum256(doc)
	t := &Tangled{Doc: path, Digest: hex.EncodeToString(sum[:])}
	var out bytes.Buffer
	emit := func(line string, docLine int) {
		out.WriteString(line)
		out.WriteByte('\n')
		t.Lines = append(t.Lines, docLine)
	}
	emit(Header+filepath.Base(path)+"; DO NOT EDIT: edit the document.", 0)
	emit(digestPrefix+t.Digest, 0)
	sc := bufio.NewScanner(bytes.NewReader(doc))
	sc.Buffer(make([]byte, 0, 64*1024), 16*1024*1024)
	var open string // the open block's fence, or "" outside one
	quint, openedAt := false, 0
	for n := 1; sc.Scan(); n++ {
		line := sc.Text()
		if open == "" {
			if m := fence.FindStringSubmatch(line); m != nil {
				open, openedAt = m[1], n
				quint = m[2] == "quint"
				if quint {
					t.Blocks++
				}
			}
			continue
		}
		// a closing fence: the same character, at least as long, nothing after
		if trimmed := strings.TrimSpace(line); strings.HasPrefix(trimmed, open) && strings.Trim(trimmed, open[:1]) == "" && len(line)-len(strings.TrimLeft(line, " ")) <= 3 {
			open = ""
			continue
		}
		if quint {
			emit(line, n)
		}
	}
	if err := sc.Err(); err != nil {
		return nil, fmt.Errorf("%s: %w", path, err)
	}
	if open != "" {
		return nil, fmt.Errorf("%s:%d: a fenced block is never closed: close it with %s", path, openedAt, open)
	}
	if t.Blocks == 0 {
		return nil, fmt.Errorf("%s: no ```quint block: a literate model's Quint is in fenced blocks whose info string is quint", path)
	}
	// the map, last: generated line ranges, each start:docStart+count
	emit(linesPrefix+encodeLines(t.Lines), 0)
	t.Source = out.Bytes()
	return t, nil
}

// encodeLines is lines as runs of consecutive document lines: each run
// "g:d+n", generated line g (1-based) from document line d, n lines.
func encodeLines(lines []int) string {
	var runs []string
	for i := 0; i < len(lines); {
		if lines[i] == 0 {
			i++
			continue
		}
		j := i + 1
		for j < len(lines) && lines[j] == lines[j-1]+1 {
			j++
		}
		runs = append(runs, fmt.Sprintf("%d:%d+%d", i+1, lines[i], j-i))
		i = j
	}
	return strings.Join(runs, ",")
}

// GeneratedPath is where doc's model is written: beside it, its extension
// .qnt.
func GeneratedPath(doc string) string {
	return strings.TrimSuffix(doc, filepath.Ext(doc)) + ".qnt"
}

// IsDoc says whether a spec path names a literate document.
func IsDoc(spec string) bool {
	ext := strings.ToLower(filepath.Ext(spec))
	return ext == ".md" || ext == ".markdown"
}

// ErrNotGenerated is a file in the generated file's place that gotogether
// did not write: Write leaves it and fails.
var ErrNotGenerated = errors.New("not generated by gotogether")

// Write tangles doc and writes its model to GeneratedPath(doc), unless
// the file there already holds exactly that (so a checkout's committed
// output is left untouched). A file there that gotogether did not
// generate is refused, never overwritten.
func Write(doc string) (*Tangled, string, error) {
	src, err := os.ReadFile(doc)
	if err != nil {
		return nil, "", err
	}
	t, err := Tangle(doc, src)
	if err != nil {
		return nil, "", err
	}
	gen := GeneratedPath(doc)
	if old, err := os.ReadFile(gen); err == nil {
		if bytes.Equal(old, t.Source) {
			return t, gen, nil
		}
		if !bytes.HasPrefix(old, []byte(Header)) {
			return nil, "", fmt.Errorf("%s: %w: it would be overwritten by %s's model; rename the document or the file", gen, ErrNotGenerated, filepath.Base(doc))
		}
	}
	// a temporary file renamed into place: bindings load in parallel
	// (tests, a roster), and a reader must never see a half-written model
	tmp, err := os.CreateTemp(filepath.Dir(gen), "."+filepath.Base(gen)+".*")
	if err != nil {
		return nil, "", err
	}
	_, werr := tmp.Write(t.Source)
	cerr := tmp.Close()
	if err := errors.Join(werr, cerr, os.Chmod(tmp.Name(), 0o644)); err != nil {
		os.Remove(tmp.Name())
		return nil, "", err
	}
	if err := os.Rename(tmp.Name(), gen); err != nil {
		os.Remove(tmp.Name())
		return nil, "", err
	}
	return t, gen, nil
}

// Check says whether gen is doc's model as Tangle makes it now: nil if
// so, else an error saying how it differs (missing, hand-written, or
// stale: its digest is another document's) and the fix.
func Check(doc string) error {
	src, err := os.ReadFile(doc)
	if err != nil {
		return err
	}
	t, err := Tangle(doc, src)
	if err != nil {
		return err
	}
	gen := GeneratedPath(doc)
	old, err := os.ReadFile(gen)
	switch {
	case errors.Is(err, os.ErrNotExist):
		return fmt.Errorf("%s: missing: run gotogether tangle %s", gen, doc)
	case err != nil:
		return err
	case !bytes.HasPrefix(old, []byte(Header)):
		return fmt.Errorf("%s: %w", gen, ErrNotGenerated)
	case !bytes.Equal(old, t.Source):
		return fmt.Errorf("%s: stale: generated from another version of %s (its digest %s, the document's %s): run gotogether tangle %s", gen, doc, short(digestOf(old)), short(t.Digest), doc)
	}
	return nil
}

func short(d string) string {
	if len(d) > 12 {
		return d[:12]
	}
	if d == "" {
		return "none"
	}
	return d
}

// digestOf is the digest a generated file records, "" if none.
func digestOf(gen []byte) string {
	for line := range strings.SplitSeq(string(gen), "\n") {
		if d, ok := strings.CutPrefix(line, digestPrefix); ok {
			return d
		}
	}
	return ""
}

// lineMap reads a generated file's map: generated line → document line.
// nil for a file gotogether did not generate.
func lineMap(gen []byte) map[int]int {
	if !bytes.HasPrefix(gen, []byte(Header)) {
		return nil
	}
	lines := strings.Split(strings.TrimRight(string(gen), "\n"), "\n")
	enc, ok := strings.CutPrefix(lines[len(lines)-1], linesPrefix)
	if !ok {
		return nil
	}
	m := map[int]int{}
	for run := range strings.SplitSeq(enc, ",") {
		g, rest, ok1 := strings.Cut(run, ":")
		d, n, ok2 := strings.Cut(rest, "+")
		gi, e1 := strconv.Atoi(g)
		di, e2 := strconv.Atoi(d)
		ni, e3 := strconv.Atoi(n)
		if !ok1 || !ok2 || e1 != nil || e2 != nil || e3 != nil {
			return nil
		}
		for k := range ni {
			m[gi+k] = di + k
		}
	}
	return m
}

// docOf is the document a generated file names, beside it.
func docOf(gen string, src []byte) string {
	first, _, _ := bytes.Cut(src, []byte("\n"))
	name, _, _ := strings.Cut(strings.TrimPrefix(string(first), Header), ";")
	return filepath.Join(filepath.Dir(gen), name)
}

// DocOf is the document gen was generated from, or gen itself when
// gotogether did not generate it: the file to name to a person.
func DocOf(gen string) string {
	src, err := os.ReadFile(gen)
	if err != nil || !bytes.HasPrefix(src, []byte(Header)) {
		return gen
	}
	return docOf(gen, src)
}

// position matches a path ending in .qnt and a 1-based line, with an
// optional column: what quint and gotogether print.
var position = regexp.MustCompile(`([^\s:"'(\[]*\.qnt):(\d+)(:\d+)?`)

// Rewrite maps every position in text that falls in a generated file
// (read from disk, relative paths against dir) to its document's line.
// A position in any other file, or on a generated line no block made,
// is left as it is.
func Rewrite(text, dir string) string {
	cache := map[string]func(int) (string, int, bool){}
	resolve := func(p string) func(int) (string, int, bool) {
		if f, ok := cache[p]; ok {
			return f
		}
		full := p
		if !filepath.IsAbs(full) {
			full = filepath.Join(dir, p)
		}
		var f func(int) (string, int, bool)
		if src, err := os.ReadFile(full); err == nil {
			if m := lineMap(src); m != nil {
				doc := docOf(p, src)
				f = func(line int) (string, int, bool) { d, ok := m[line]; return doc, d, ok }
			}
		}
		cache[p] = f
		return f
	}
	return position.ReplaceAllStringFunc(text, func(s string) string {
		g := position.FindStringSubmatch(s)
		f := resolve(g[1])
		if f == nil {
			return s
		}
		line, _ := strconv.Atoi(g[2])
		doc, d, ok := f(line)
		if !ok {
			return s
		}
		return fmt.Sprintf("%s:%d%s", doc, d, g[3])
	})
}

// definition matches a top-level definition's name in a Quint line.
var definition = regexp.MustCompile(`^\s*(?:pure\s+)?(?:val|def|action|temporal|run)\s+([A-Za-z_][A-Za-z0-9_]*)`)

// Definitions are the line each name is defined on in the document (the
// first, where names repeat across modules): where a report points for a
// val or an action of a literate model.
func (t *Tangled) Definitions() map[string]int {
	defs := map[string]int{}
	lines := strings.Split(string(t.Source), "\n")
	for i, line := range lines {
		if i >= len(t.Lines) || t.Lines[i] == 0 {
			continue
		}
		if m := definition.FindStringSubmatch(line); m != nil {
			if _, ok := defs[m[1]]; !ok {
				defs[m[1]] = t.Lines[i]
			}
		}
	}
	return defs
}

// Sources are where each top-level definition of the model at spec is
// (the first, where names repeat): "doc.md:21" for a generated model's,
// "model.qnt:21" for any other. name is how the result names the file
// (the path as the caller wants it shown). nil if spec cannot be read.
func Sources(spec, name string) map[string]string {
	src, err := os.ReadFile(spec)
	if err != nil {
		return nil
	}
	m := lineMap(src)
	shown := name
	if m != nil {
		shown = strings.TrimSuffix(name, filepath.Ext(name)) + filepath.Ext(docOf(spec, src))
	}
	out := map[string]string{}
	for i, line := range strings.Split(string(src), "\n") {
		d := i + 1
		if m != nil {
			var ok bool
			if d, ok = m[i+1]; !ok {
				continue
			}
		}
		if g := definition.FindStringSubmatch(line); g != nil {
			if _, ok := out[g[1]]; !ok {
				out[g[1]] = fmt.Sprintf("%s:%d", shown, d)
			}
		}
	}
	return out
}

// Matrix markers bound the place in a document where `gotogether simulate
// -matrix -write-matrix` writes the design matrix: everything between
// them is replaced, everything outside left as it is.
const (
	MatrixBegin = "<!-- gotogether:matrix -->"
	MatrixEnd   = "<!-- /gotogether:matrix -->"
)

// WriteMarked replaces what lies between doc's begin and end markers (each
// alone on its line, once) with content, and writes doc only when that
// changes it. A document without the markers, or with them out of order or
// repeated, is an error naming what to add.
//
// A literate document's generated model records the document's digest
// and line map, which any edit changes, prose and tables included: when
// that model was current before the write it is written again after it,
// so writing a matrix into a binding's own document never leaves its
// model stale for `tangle -check` (Goo found that order a trap). A model
// already stale, missing or hand-written is left as it was, for -check to
// report.
func WriteMarked(doc, begin, end, content string) (changed bool, err error) {
	if IsDoc(doc) && Check(doc) == nil {
		defer func() {
			if changed && err == nil {
				_, _, err = Write(doc)
			}
		}()
	}
	src, err := os.ReadFile(doc)
	if err != nil {
		return false, err
	}
	out, err := replaceMarked(doc, string(src), begin, end, content)
	if err != nil || out == string(src) {
		return false, err
	}
	return true, os.WriteFile(doc, []byte(out), 0o644)
}

// CheckMarked says whether doc's text between its begin and end markers
// is content already, writing nothing: the check of a document's matrix
// in CI (simulate -check-matrix). A document without the markers is the
// same error as WriteMarked's.
func CheckMarked(doc, begin, end, content string) (current bool, err error) {
	src, err := os.ReadFile(doc)
	if err != nil {
		return false, err
	}
	out, err := replaceMarked(doc, string(src), begin, end, content)
	return err == nil && out == string(src), err
}

// replaceMarked is src with what lies between its markers replaced by
// content.
func replaceMarked(doc, src, begin, end, content string) (string, error) {
	// markers as whole lines: the text with a newline before its first,
	// so one on the document's first line is found as any other
	text := "\n" + src
	bm, em := "\n"+begin+"\n", "\n"+end+"\n"
	if !strings.HasSuffix(text, "\n") {
		text += "\n"
	}
	b, e := strings.Index(text, bm), strings.Index(text, em)
	switch {
	case b < 0 || e < 0:
		return "", fmt.Errorf("%s has no %s ... %s: add the two lines where the matrix goes, each alone on its line", doc, begin, end)
	case strings.Count(text, bm) > 1 || strings.Count(text, em) > 1:
		return "", fmt.Errorf("%s has %s or %s more than once: keep one pair", doc, begin, end)
	case e < b:
		return "", fmt.Errorf("%s has %s before %s: put the begin marker first", doc, end, begin)
	}
	out := text[:b+len(bm)] + strings.TrimRight(content, "\n") + text[e:]
	out = out[1:] // the newline added before the first line
	if !strings.HasSuffix(src, "\n") {
		out = strings.TrimSuffix(out, "\n")
	}
	return out, nil
}
